</section></div>
<script>
(()=>{const $=id=>document.getElementById(id);const select=$('leadSelect'),goal=$('goal'),offer=$('offer'),tone=$('tone'),subject=$('subject'),message=$('message'),count=$('charCount'),feedback=$('feedback');
function updateCount(){count.textContent=message.value.length+' characters'}
function generate(){const opt=select.options[select.selectedIndex];const name=opt?.dataset?.name||'there';const first=name.split(' ')[0]||'there';const company=opt?.dataset?.company||'your team';const role=opt?.dataset?.role;const value=offer.value.trim()||'exchange ideas around practical growth opportunities';let opening='Hi '+first+',',body='';if(tone.value==='direct')opening='Hello '+first+',';if(tone.value==='casual')opening='Hey '+first+',';
if(goal.value==='connect'){body=`I noticed your work${role?' as '+role:''}${company?' at '+company:''} and wanted to connect. ${value} No pressure — I’d be glad to stay in touch.`;subject.value='';}
else if(goal.value==='intro'){body=`I’m reaching out because your work${company?' at '+company:''} caught my attention. ${value} If this is relevant to your current priorities, I’d be happy to share a little more. Either way, thanks for connecting.`;subject.value='A relevant idea to share';}
else if(goal.value==='followup'){body=`Thanks for connecting, ${first}. I wanted to follow up with a little context: ${value} If it’s useful, I’d be glad to compare notes. If now isn’t the right time, no worries at all.`;subject.value='Following up on our connection';}
else{body=`I’m reaching out because ${value} Given your work${company?' at '+company:''}, I thought a short conversation could be useful. Would you be open to a brief 15-minute chat sometime next week? Happy to work around your schedule.`;subject.value='Would a brief conversation be useful?';}
message.value=opening+'\n\n'+body+'\n\nBest,\n[Your name]';updateCount();feedback.textContent='Draft generated — personalize and verify it before sending.';}
async function copy(text){if(!text.trim()){feedback.textContent='Generate or write a message first.';return}try{await navigator.clipboard.writeText(text);feedback.textContent='Copied to clipboard.'}catch(e){const t=document.createElement('textarea');t.value=text;document.body.appendChild(t);t.select();const ok=document.execCommand('copy');t.remove();feedback.textContent=ok?'Copied to clipboard.':'Clipboard unavailable — select and copy the text manually.'}}
$('generate').addEventListener('click',generate);message.addEventListener('input',updateCount);$('copyMessage').addEventListener('click',()=>copy(message.value));$('copyAll').addEventListener('click',()=>copy((subject.value.trim()?subject.value.trim()+'\n\n':'')+message.value));$('clearDraft').addEventListener('click',()=>{subject.value='';message.value='';updateCount();feedback.textContent='Draft cleared.'});select.addEventListener('change',()=>{const opt=select.options[select.selectedIndex];if(opt?.dataset?.company)subject.placeholder='A quick idea for '+opt.dataset.company});if(select.value)generate();updateCount();})();
</script>
